<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\ValidationException;use App\Models\User;use App\Services\ActivityLogService;use Illuminate\Support\Facades\Password;use Illuminate\Support\Str;
class AuthController extends Controller { public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string','remember'=>'nullable|boolean']);$u=User::where('email',$d['email'])->where('is_active',true)->first();if(!$u||!Hash::check($d['password'],$u->password))throw ValidationException::withMessages(['email'=>'The provided credentials are incorrect.']);$token=$u->createToken('admin-dashboard',['admin'])->plainTextToken;ActivityLogService::record('Login',$u,null,null,$r,'Admin logged in');return response()->json(['token'=>$token,'user'=>['id'=>$u->id,'name'=>$u->name,'email'=>$u->email,'role'=>$u->role]]);} public function forgotPassword(Request $r){$d=$r->validate(['email'=>'required|email']);$status=Password::sendResetLink($d);return $status===Password::RESET_LINK_SENT?response()->json(['message'=>__($status)]):throw ValidationException::withMessages(['email'=>__($status)]);}
 public function resetPassword(Request $r){$d=$r->validate(['token'=>'required','email'=>'required|email','password'=>'required|string|min:10|confirmed']);$status=Password::reset($d,function(User $user,string $password){$user->forceFill(['password'=>$password,'remember_token'=>Str::random(60)])->save();$user->tokens()->delete();});return $status===Password::PASSWORD_RESET?response()->json(['message'=>__($status)]):throw ValidationException::withMessages(['email'=>__($status)]);}
 public function logout(Request $r){$token=$r->user()?->currentAccessToken();if($token)$token->delete();return response()->json(['message'=>'Logged out.']);} }
